def chk_bookwide():
    """书级体检（191章末立）：补十轮系统之唯一盲区——章级之闸看不见跨章之漂。
    六检：人物在场衰减／章型连锁／账之净额／日数速率／距终点与账之余额／轮记开销比。"""
    out = run('书级体检', ['工具/书级体检.py', '--静'])
    if out is None:
        return False, '运行失败'
    if '书级体检通过' in out:
        return True, '六检皆过'
    bad = [ln.strip().lstrip('⛔ ') for ln in out.splitlines() if '⛔' in ln]
    return False, '；'.join(bad[:3]) if bad else '未通过'


def chk_quality_gates():
    """质量三闸（2026-08-15立·见 设定/02_全书之约_逐站事数表.md）：
    ★闸①一章一事（防一章塞多事）／★★闸②脉象不相犯（防站与站重复）／★★★闸③谜底之距（防吊太久）。
    ★★★★而其立之由：全书重排为约450章之后，章级十轮之闸仍看不见「质量之三敌」。
    ⛔★★★★★**2026-09-23·限362 补一路（本坐当日拆「赤手无负测」时所逮之系统病）**：
      ★**盘上多样器各自带着一份 `自测()`，而全测通篇无一格跑它**——
        **逐样亲数得九样**（起手哨／含拍／FS闸／亮点在／净重对表／质量三闸／字数闸 等）；
        ⛔**於是那几十格逐日躺着，谁也不知道它们今日还过不过得去。**
      ★★**今补**：**本格先跑 `--自测`，不满格即红；再跑其报。**
      ⛔**此改令本格更严，不更宽。**
      ★★★**并及其限**：**跑得过它自己那几格，⛔不等於它测着了什么**——
        **那是它自己造的局；一份真负测该拿「真犯过此病之原物」去撞它**（令§一⑤）。
        """
    _zi = run('质量三闸·自测', ['工具/质量三闸.py', '--自测'])
    if _zi is None:
        return False, '自测运行失败'
    import re as _r0
    _mz = _r0.search(r'── (\d+)/(\d+) 全通', _zi)
    if not _mz:
        return False, '自测未见其数'
    if _mz.group(1) != _mz.group(2):
        return False, '自测未满格 %s/%s' % (_mz.group(1), _mz.group(2))
    out = run('质量三闸', ['工具/质量三闸.py'])
    if out is None:
        return False, '运行失败'
    if '三闸皆过' in out:
        return True, '三闸皆过'
    bad = [ln.strip() for ln in out.splitlines() if '⛔' in ln]
    return False, '；'.join(bad[:3]) if bad else '未通过'


_六检之号 = '①②③④⑤⑥⑦⑧⑨⑩⑪⑫⑬⑭⑮⑯⑰⑱⑲⑳㉑㉒㉓㉔㉕㉖㉗㉘㉙㉚㉛㉜'


def _软报之号():
    """★取 `开轮六检.py` 自己那份「报而不拦」之名单（⛔从其码里读，不在此处自造一份）。
    ★★其由（0913·323 推时自逮）：`开轮六检.py 323 --静` **自判 rc=0（它判通过）**，
      而⑰之文照旧随印带出；**全测这一路把印出来的字当红**，
      **遂把一条对方已判绿的警，变成了拦推的红。**
    ⛔**这不是放松闸**：⑰ 之 docstring 自书「报而不拦」，其 `_软报` 列里本就有它，
      **且其注逐字写着「其治不在本章之文（⑰读的是已写各章之形，须待下一章落笔才解），遂逼人绕闸」。**
    ⛔**而只认这一份名单，一条也不自己添**——**名单谁定，闸就谁说了算；
      我若在这里另写一份，等於自己给自己发通行证。**"""
    import re as _re
    try:
        _s = open(os.path.join(ROOT, '工具', '开轮六检.py'),
                  encoding='utf-8', errors='replace').read()
        _m = _re.search(r"^_软报\s*=\s*\(([^)]*)\)", _s, _re.M)
        if not _m:
            return ()
        return tuple(x.strip().strip("'\"")
                     for x in _m.group(1).split(',') if x.strip())
    except Exception:
        return ()


def _六检之败(_t, _免十四):
    """把 `开轮六检.py --静` 之印拆成**逐条**之败（2026-09-09·307封版席所逮而立）。

    ★病灶（本日磁盘之实，逐条印过）：`--静` 之印把当日所有之红以「；」串成**一行**
      （其码：`'；'.join('%s %s' % (n, m) for n, ok, m in rows if not ok)`），
      ★★而旧式 `_bad` 是逐**行**判的：`if _skip14 and ('⑭' in _x or '已封版' in _x): continue`
      ——**见行内有⑭即整行跳过**；★★★於是那一行上与⑭同列的每一条红，**一并被吞**。
    ★★★★其实证：`python3 工具/开轮六检.py 307 --静` 印
      「⑨·领轮之号 ⛔基线里无「目标轮」…；⑭·已封版之章 ⛔第307章已封版…」（rc=2），
      而同一日之全测印「✓ 开轮十六检　两头俱过（末章第307章·下章第308章）」——
      **⑨那一条红从来没有进过 fails，故推闸连开都没开过**：
      ★这不是「靠跑轮档放行过去的」，是**红在半路上就没了**，比放行更看不见。
    ★★★★★故改逐**条**判。而不许裸 `split('；')`：**各条自身之文里亦带「；」**
      （⑭之文即含「而今之末章为第307章；★★★★下一章为第308章。」），
      故断在「；」而其後紧接一个检号（①…㉜）之处，只跳⑭那一条。
    """
    import re as _re
    _b = []
    for _ln in (_t or '').splitlines():
        _x = _ln.strip()
        if not _x or '开轮十六检通过' in _x:
            continue
        for _c in _re.split('；(?=[' + _六检之号 + '])', _x):
            _c = _c.strip()
            if not _c:
                continue
            if _免十四 and _c.startswith('⑭'):
                continue
            _b.append(_c)
    return _b


def chk_open_six():
    """开轮六检（2026-08-16立·见 工具/开轮六检.py）：治近日所逮之六条未治之bug——
    ★③人名计数之误／★★⑤撞号与merged／★★★⑥冷轮逾期／
    ★★★★⑦锚之长／★⑨领轮之号／★★⑩招五之第二形。"""
    # ★2026-08-17 订：全测无参调用，开轮检遂取末章；
    # ★★而末章已封版时，⑭必报——★★★而那不是伤，是全测取错了章。
    # ★★★★遂改：取「下一章」（末章＋1）——★而其正是开轮检该测之章。
    import glob as _g, os as _o, re as _r
    _CN = {'一': 1, '二': 2, '三': 3, '四': 4, '五': 5,
           '六': 6, '七': 7, '八': 8, '九': 9, '十': 10}

    def _cn(_p):
        _m = _r.search(r'第([零〇一二三四五六七八九十百]+)章', _o.path.basename(_p))
        if not _m:
            return -1
        _s = _m.group(1)
        _t = _n = 0
        for _ch in _s:
            if _ch in _CN and _ch != '十':
                _n = _CN[_ch]
            elif _ch == '十':
                _t += (_n or 1) * 10
                _n = 0
            elif _ch == '百':
                _t += (_n or 1) * 100
                _n = 0
        return _t + _n
    _cs = [_cn(x) for x in _g.glob('正文/*.md')]
    _cs = [x for x in _cs if x > 0]
    _last = max(_cs) if _cs else 1
    _nx = _last + 1
    # ★★★★★2026-09-02·九席审读所逮·当日治：
    #   ★**旧式只跑「末章＋1」，而那一章尚未起草**——十六检里 ⑬⑮⑱⑳ 一律自赦
    #     （「正文缺，免测」），③⑩ 连印都没印，**当真读了文字的只有 ⑰⑲ 两条**；
    #   ★★**即：57项里这一个绿勾，覆盖的是一个不存在的章**，且它掩护着底下六道
    #     本来能报红的检。★★★这正是令§一⑤：**不是查过了判无罪，是压根没查。**
    #   ★★★★故今两头都跑：**末章（有正文，真读得着）＋末章＋1（该起草之章）**；
    #     ★而末章那一趟须摘掉 ⑭——**⑭之职正是「拿已封版之章重跑即报」**，
    #     它在审计之下必红，而那一红不是伤，是它认得出我在审计。
    _o1 = run('开轮十六检·末章', ['工具/开轮六检.py', str(_last), '--静'])
    _o2 = run('开轮十六检·下章', ['工具/开轮六检.py', str(_nx), '--静'])
    _RAW['开轮十六检'] = (_o1 or '') + '\n' + (_o2 or '')
    if _o1 is None or _o2 is None:
        return False, '运行失败'
    _b1, _b2 = _六检之败(_o1, True), _六检之败(_o2, False)
    if not _b1 and not _b2:
        return True, '两头俱过（末章第%d章·下章第%d章）' % (_last, _nx)
    _m = []
    if _b1:
        _m.append('末章第%d章：%s' % (_last, '；'.join(_b1[:2])))
    if _b2:
        _m.append('下章第%d章：%s' % (_nx, '；'.join(_b2[:2])))
    return False, '｜'.join(_m)





def chk_hard_gate():
    """硬闸·单一真源 负测（2026-09-01立·见 工具/负测_硬闸.py）。
    ★其立之由：硬项之集先前散在跑轮／预检／检察官三处，遂成两本账——
    ★★实测一段含 `? ! ;`、九鼎、赵阙、「那个那个」之稿跑预检，只报「英文」与「段间空行」。
    ★★★而此测除验新格外，另有一路要紧：**旧十三格拿全书回灌，一格不许走样**。"""
    out = run('负测·硬闸', ['工具/负测_硬闸.py'])
    if out is None:
        return False, '运行失败'
    if '全通' not in out:
        return False, out.strip().split('\n')[0]
    if '非陪跑' not in out:
        return False, '★此测在旧式下亦全过，是陪跑之测'
    return True, out.strip().split('｜', 1)[0].replace('✓ 负测·硬闸 ', '')


