def chk_highlight_present():
    """亮点在（2026-09-06 晚立·见 工具/亮点在.py）——**骨记在不在**。
    ★其立之由：246 之修席进场时发现 246 一章根本没有【本章亮点】段，
    　而 亮点对表 与 起草闸甲层 照样报全绿——三路皆以 `if '【本章亮点】' not in txt: return` 起手，
    　**无段即无判据，於是无段就是全绿**。此为「绿而不实」之**第五种**：
    　有位、红得起来、看得见、也接进了「过不过」那一句，
    　**可遇上「整样东西不在」的时候，它是空过，不是判红**。
    ★★其群与其不认（令§六④）：认第 109 章以後之章（本书 197 章），骨记须恰一段；
    　1—108 章共 100 章无骨记，係立式以前之旧稿，**不认**——
    　若一并判红，此器天天红一百处，就成了没人看的红。那一批记在 机制总审§二十六。
    ★★★它红在哪一行（令§十三）：立此器之日红四处——280／281／282／283，同日补齐。
    ⛔★★★★★**2026-09-23·限362 补一路（本坐当日拆「赤手无负测」时所逮之系统病）**：
      ★**盘上多样器各自带着一份 `自测()`，而全测通篇无一格跑它**——
        **逐样亲数得九样**（起手哨／含拍／FS闸／亮点在／净重对表／质量三闸／字数闸 等）；
        ⛔**於是那几十格逐日躺着，谁也不知道它们今日还过不过得去。**
      ★★**今补**：**本格先跑 `--自测`，不满格即红；再跑其报。**
      ⛔**此改令本格更严，不更宽。**
      ★★★**并及其限**：**跑得过它自己那几格，⛔不等於它测着了什么**——
        **那是它自己造的局；一份真负测该拿「真犯过此病之原物」去撞它**（令§一⑤）。
        """
    _zi = run('亮点在·自测', ['工具/亮点在.py', '--自测'])
    if _zi is None:
        return False, '自测运行失败'
    import re as _r0
    _mz = _r0.search(r'自测 (\d+)/(\d+)', _zi)
    if not _mz:
        return False, '自测未见其数'
    if _mz.group(1) != _mz.group(2):
        return False, '自测未满格 %s/%s' % (_mz.group(1), _mz.group(2))
    out = run('亮点在', ['工具/亮点在.py'])
    if out is None:
        return False, '运行失败'
    if '⛔' in out:
        return False, [x.strip() for x in out.split('\n') if '⛔' in x][0]
    ln = [x.strip() for x in out.split('\n') if '✓' in x]
    return True, (ln[0] if ln else '全绿') + '｜W35：负测_亮点在已退（其格由 --自测 管）'


