def _留旗之章(章目录们, 有回执):
    """纯函数：返回既有回执（已封版）又留着 _拦停.json 之章号列表。"""
    return [n for n, d in 章目录们 if 有回执(n) and os.path.exists(os.path.join(d, '_拦停.json'))]


