def _分量之判(out2):
    """★把 `分量闸` 正路之印读成一个判：(过否, 其语)。⛔**单拆出来，好教负测拿得住它**
    （`工具/负测_分量闸之读.py`·2026-09-23·限359 同日立）。"""
    import re as _r
    _真红 = _r.search(r'⛔ 分量闸：(\d+) 章不足而无豁免', out2)
    olds = _r.findall(r'⚠第(\d+)章：净重', out2)
    if _真红:
        reds = _r.findall(r'⛔第(\d+)章：净重 \d+ ＜ \d+（[^）]*），且施工表无', out2)
        return False, ('⛔不足而无豁免：第%s章' % '、第'.join(reds or [_真红.group(1) + '（其数）']))
    if '⛔末五篇暗线' in out2:
        return False, ('⛔暗线之厚未过：%s'
                       % (_r.search(r'⛔末五篇暗线[^\n]*', out2).group(0)[:90]))
    # ★0924 裁（`设定/裁_0924_额破只报不拦推.md`）：额破照「认欠只不入拦」——闸已改作只报，而本读仍把那一行判红，
    #   **裁在闸里生效了、在推闸这一处没生效**（作者当面所斥之「做了的决定没生效」即此形）。今照裁改：
    #   ⛔额破期间又认欠 → 红；额破而闸自书「只报不拦」→ 照报不拦。
    if '额破期间又认欠' in out2:
        return False, ('⛔额破期间又认欠：%s'
                       % (_r.search(r'⛔额破期间又认欠[^\n]*', out2).group(0)[:90]))
    if _r.search(r'⛔[^\n]*认欠之额', out2) and '额破·只报不拦' not in out2:
        return False, ('⛔认欠之额已破：%s'
                       % (_r.search(r'⛔[^\n]*认欠之额[^\n]*', out2).group(0)[:90]))
    return True, ('新章皆足量（旧章只报不拦 %d 章·其账在 设定/分量欠账.md）' % len(olds))


def chk_fenliang():
    """★分量闸（2026-09-15 立·执 `F087_分量反向闸`）：**作者立过一条硬线，而盘上没有一样东西在量它。**
    ⛔**其令逐字**：「新章(≥73章)<2500字＝硬错，施工表『第 N 章短章豁免＋理由』可解……加厚＝补该演没演的慢镜头，⛔禁注水。」
    ★**而这张卡 `forbid` 係空表、`checker` 亦无**（`无闸之卡账` 上那 19 张之一）——
      **於是「ERROR 卡正则 430 条命中 0」年年印着，而这一条从来没有人量过。**
    ★★**0915 逐章亲数**：≥73 章而 <2500 者 **18** 章；其中施工表已出短章豁免者 **5**；⛔**未豁免 13 章**。
    ★★★**起=334 硬拦，此前只报不拦**：其治係「补该演没演的慢镜头」，**那是十三章真活，不是一道闸能了的**；
      ⛔**而不许给它们补一张豁免了事——那是把十三笔欠一次抹平。**逐章列名在 `设定/分量欠账.md`。"""
    out = run('分量闸·自测', ['工具/分量闸.py', '--自测'])
    if out is None:
        return False, '运行失败'
    import re as _r
    m = _r.search(r'自测 (\d+)/(\d+)', out)
    if not m or m.group(1) != m.group(2):
        return False, '自测未满格：%s' % (m.group(0) if m else '未见其数')
    out2 = run('分量闸', ['工具/分量闸.py'])
    if out2 is None:
        return False, '正路运行失败'
    # ⛔★★★★★2026-09-23·限359（本坐今日核推闸之红时所逮）：
    #   ★**旧式以 `⛔第N章：净重` 一个字头去数其红**——**而 `分量闸` 拿同一个字头印三样东西**：
    #     ①**真红**（不足而无豁免·其文末带「且施工表无「第N章短章豁免」」）；
    #     ②⛔**认欠之章**（其文末逐字带「**认欠·章已封版·治不得**」——
    #       **而那一行自己写着「其欠一笔未抹，⛔只不入拦」**）；③其额之语。
    #   ⛔**於是 349／352 两笔当面认过、当面写明不入拦的欠，在本器这里照旧拦着推**——
    #     **`分量闸` 自己判「不入拦」，而 `全测` 拿它印出来的字把它拦了。**
    #     ★**其形与本日 `听针` 那一笔同**：**一道把已经结过的账再拦一回的闸，教人把红当噪声。**
    #   ★★**今不另立一式去数**，**改读 `分量闸` 自己那一句判**——
    #     ⛔**它印「⛔ 分量闸：N 章不足而无豁免」方算真红**；**只有 `认欠` 之行者不算。**
    #     ★**其非陪跑之凭**：**`分量闸` 之 `return 1` 三路（新红／`_厚过`／`_额过`）今皆由其判语接得着**，
    #     **而下面 `暗线之厚`／`认欠之额` 二路本器同日补上，⛔一路也没有放掉。**
    _ok2, _lang = _分量之判(out2)
    olds = _r.findall(r'⚠第(\d+)章：净重', out2)
    if not _ok2:
        return False, _lang
    return True, ('%s·新章皆足量（旧章只报不拦 %d 章·其账在 设定/分量欠账.md）' % (m.group(0), len(olds)))


def 判末行(out, 项名):
    """★2026-09-16 立：**问那一件器的判语行，不问它印里有没有那一个字。**

    ⛔**其所由来·`chk_wuzha` 之假红**：其判旧作 `if '⛔' in out2`，
    **而 `无闸之卡.py` 自己的栏目之标里就带着那一个字**
    （`ERROR 卡 176 张：有正则 156｜无正则而有验码 1｜⛔无正则亦无验码 19`）——
    **於是它每一回都红，而其末行印的是 `✓ 无闸之卡：无闸者 19 张，账上逐张有名且其数相符`（rc=0）。**
    ★★**更坏的一层**：旧式红了之後去捡「以⛔起头之行」，**一行也捡不着**（那个字在行中不在行首），
    **遂回一句 `账与今数不符`——一句它根本没有验过的话。**⛔**假红比假绿更难查，因为它看着像在干活。**

    ★**本函之判只一条**：**取其末一个非空行，须以 `✓<项名>` 起头。**
    ⛔**不许再拿「印里有没有某个字」去判一件器的成败**——**那个字可能是它栏目的一部分。**
    """
    行 = [l.rstrip() for l in (out or '').splitlines() if l.strip()]
    if not 行:
        return False, '无印'
    末 = 行[-1].strip()
    if 末.startswith('✓' + 项名) or 末.startswith('✓ ' + 项名):
        return True, 末
    return False, 末[:90]


def chk_moxing_neg():
    """★负测·末行之判（2026-09-16 立·治 `chk_wuzha` 之假红）：
    ⛔**旧判作 `if '⛔' in out2`，而 `无闸之卡.py` 自己的栏目之标里就带着那一个字**，
      **其末行实印 `✓ 无闸之卡：…`（rc=0、自测 12/12）**——**於是它每一回都红。**
    ★★**更坏的一层**：旧式红了之後去捡「以⛔起头之行」，**一行也捡不着**（那字在行中不在行首），
      **遂回一句「账与今数不符」——一句它根本没有验过的话。**
    ⛔**假红比假绿更难查，因为它看着像在干活。**
    ★**本负测每一格皆同笔跑一遍旧式并验它确实错**——⛔**旧式也过者即陪跑，不算负测。**"""
    out = run('负测·末行之判', ['工具/负测_末行之判.py'])
    if out is None:
        return False, '运行失败'
    好, 末 = 判末行(out, '负测·末行之判')
    return (True, 末) if 好 else (False, 末)


