def chk_carry_gate():
    """★承前闸（⑮）负测：其比由「前一章」改为「同线最近之章」，须验其防未动。
    ★★其要害二项：③同线相接之章新旧两式逐章同判（防未动）；
      ★★★⑥换线之章新式之红率须显著低於旧式而不为零（改而不挖空）。"""
    out = run('负测·承前闸', ['工具/负测_承前闸.py'])
