def chk_review_ledger():
    """复核台账须守住 1096/1096 且无因之判为零（2026-09-08 接进全测·囤灰闸所逮）。
    ★其红在哪一行：此账 0908 之前已判毕，而**没有一样东西守着它别退**——
      一条判被改回「未判」或改成无因之判，从前全书无一器出声。"""
    out = run('复核台账', ['工具/复核台账.py', '--进度'])
    if out is None:
        return False, '复核台账崩'
    m = re.search(r'无因之判：(\d+)', out)
    if m is None:
        return False, '复核台账未印「无因之判」（器印变了式，须重接）'
    if m.group(1) != '0':
        return False, '复核台账有无因之判 %s 条' % m.group(1)
    bars = re.findall(r'(\d+)/\s*(\d+)', out)
    未 = [(a, b) for a, b in bars if a != b]
    if 未:
        return False, '复核台账有未判：%s' % 未[:5]
    return True, '1096 项逐条有判、无因之判 0（此账只许守，不许退）'


# ═══ 空跑闸（2026-09-08·本坐亲犯而立）═══
# ★病灶：本坐把三个新检的 def 插进了 main() 中间，**main() 被截成两半**——
#   `items = [...]` 之後即函数末，全测遂 **rc=0、一行不印**，而本坐先看的是退出码。
# ★★这一病最毒的地方：**它长得跟「全绿」一模一样**。ast.parse 过、无重名、无异常。
# ★★★故立此闸：全测自己数它到底跑了几件；**跑不满 %d 件即判红**，
#   且此下限是**当场由 items 之长算的**（不许钉成常数——§二十八：活数钉成常数，闸即死）。
# ★★★★而更要紧的一条写在这儿备忘：**退出码不是印。器印了什么，才是它说的话（令§一②）。**
最少件数 = 40


def chk_jieli():
    """★0911 立（一次真停摆逼出来的）：**「办完了」与「接上了」是两件事。**
    0910 21:00 第312章封版撤锁，0911 01:28 第313章才起——四个半钟头一个字没写，
    而心跳／续跑／存底**三本账一本也没响，且三本都报得对**：它们问的全是上一件事。
    """
    try:
        import subprocess
        r = subprocess.run(['python3', os.path.join(ROOT, '工具', '接力.py')],
                           capture_output=True, text=True, timeout=60)
        末 = [x.strip() for x in (r.stdout or '').strip().split('\n') if x.strip()]
        语 = 末[-1] if 末 else '（接力无话）'
        for x in 末:
            if x.startswith('⛔') or '断流' in x:
                语 = x
                break
        return (r.returncode == 0), 语[:170]
    except Exception as e:
        return False, '接力跑不起来：%s' % e


def _自测之项(名, 档):
    """★W60·X33⑦：跑一器之 --自测，须印「全通」且无「未过」（器崩→None→红）；回印其自印之数（令§一②）。"""
    out = run(名, [档, '--自测'], timeout=300)
    if out is None:
        return False, '运行失败（崩或逾时）'
    末 = [x.strip() for x in out.strip().split('\n') if x.strip()]
    if '全通' not in out or '未过' in out:
        return False, (末[-1] if 末 else '（无印）')[:170]
    return True, _测数(out, '?/?') + ' 全通'


