def 只跑(名们, 出, quick):
    """★1017 W51：`--只 名,… [--出 档]`——只跑所列之项（取自 诸项()，⛔另写），每项印一行同 main；
    以 JSON 交其果 {果: [[名, 过, 语, 秒]], 未认: [...]} 於 出（全测并.py 於工作副本中逐项调之）。
    ⛔不记器账、⛔不查留字（并行之驱於副本以 git status 查之、主仓库之项以 _留字快照 查之）。"""
    表 = dict(诸项(quick))
    果, 未认 = [], [n for n in 名们 if n not in 表]
    for 名 in 名们:
        if 名 not in 表:
            continue
        _t0 = time.time()
        try:
            ok, detail = 表[名]()
        except Exception as _e:
            ok, detail = False, '⛔器崩：%r' % (_e,)
        果.append([名, bool(ok), str(detail), round(time.time() - _t0, 2)])
        print('  %s %-14s %s' % ('✓' if ok else '✗', 名, detail))
    if 出:
        import json as _j
        _j.dump({'果': 果, '未认': 未认}, open(出, 'w', encoding='utf-8'), ensure_ascii=False)
    return 0 if (not 未认 and all(x[1] for x in 果)) else 1


def 补浅克隆():
    """★1022 W64（403 推闸逮）：云端会话係浅克隆，负测之钉於旧笔者（负测·全测崩绿之 a73c8836、负测·含拍）git show 得空而诬红——先补全史一回（零 token；已全者不动）。"""
    try:
        if subprocess.run(['git', 'rev-parse', '--is-shallow-repository'], cwd=ROOT, capture_output=True, text=True).stdout.strip() == 'true':
            subprocess.run(['git', 'fetch', '-q', '--unshallow', 'origin'], cwd=ROOT, capture_output=True, timeout=600)
    except Exception:
        pass


def main():
    补浅克隆()
    quick = '--快' in sys.argv
    if '--只' in sys.argv:
        _a = sys.argv
        _名 = [x for x in _a[_a.index('--只') + 1].split(',') if x] if _a.index('--只') + 1 < len(_a) else []
        _出 = _a[_a.index('--出') + 1] if '--出' in _a and _a.index('--出') + 1 < len(_a) else None
        return 只跑(_名, _出, quick)
    items = 诸项(quick)
    print('\n████ 全测 · %d 项 ████' % len(items))
    _席凭 = _有席在跑()
    if _席凭:
        print('  ⚠ **本次係带席而跑**（%s）——**下列诸红须逐条分辨真假**：'
              '正在写的那一章尚无席记、下一章尚无开镜卡，皆係时序不是病。'
              '★待席收毕、仓里安静时再跑一回，那一回才算数。' % '、'.join(_席凭))
        print('     ★**带席而跑时，这几道多半是同一个根**（0910 实查）：'
              '席每改一轮文，**阅读器即过期**，而 检察官自测／医生／全书检 三项俱据之报红；'
              '而阅读器是封版之序才重生的。**三红一根，不是三处病。**')
    fails = []
    跑过件数 = [0]
    _快照 = _留字快照()
    _器录 = []
    for name, fn in items:
        跑过件数[0] += 1
        _t0 = time.time()
        ok, detail = fn()
        _器录.append((name, bool(ok), time.time() - _t0, str(detail)))
        print('  %s %-14s %s' % ('✓' if ok else '✗', name, detail))
        if not ok:
            fails.append(name)
    _记器账(_器录, quick)
    # ★负测留字之查（2026-09-05）：跑毕再照一回，凡 设定／版本／正文 之内容有变、有增、有失者，即负测留字。
    _变, _增, _失 = _留字之差(_快照)
    if _变 or _增 or _失:
        席凭 = _有席在跑()
        if 席凭:
            # ★带席而跑：这几档多半是那一席正在写的，**不是负测偷改的**。
            #   报黄、写明其凭，**不入 fails**——否则一道假红会把一章的封版推闸堵死。
            print('  ⚠ %-14s **本次係带席而跑**（%s）：内容有变 %d｜新增 %d｜消失 %d：%s' % (
                '负测留字', '、'.join(席凭), len(_变), len(_增), len(_失),
                '、'.join((_变 + _增 + _失)[:6])))
            print('     ★下列诸红须逐条分辨真假；**待席收毕、仓里安静时再跑一回全测**，那一回它才算数。')
        else:
            print('  ✗ %-14s 内容有变 %d｜新增 %d｜消失 %d：%s' % (
                '负测留字', len(_变), len(_增), len(_失), '、'.join((_变 + _增 + _失)[:6])))
            print('     ★某份负测改了真仓库之档而未复原（多半是中途崩了或被超时所杀）——先 git diff 看它改了什么，再定复原。')
            fails.append('负测留字')
    else:
        print('  ✓ %-14s 设定／版本／正文 %d 档，跑前跑後 sha256 逐档同' % ('负测留字', len(_快照)))
    if 跑过件数[0] < (最少件数 if not quick else 8):
        print('\n  ⛔空跑闸：本次只跑了 %d 件（至少 %d）——多半是 main() 被截断或 items 没接上。'
              % (跑过件数[0], 最少件数 if not quick else 8))
        print('     ★此病长得跟全绿一模一样：rc=0、一行不印。**退出码不是印**（令§一②）。')
        return 1
    if fails:
        print('\n  ⛔全测未过：%s' % '、'.join(fails))
        ok, 语 = 推闸(fails)
        print('  %s' % 语)
        if not ok:
            print('  【批115】不过不许推——pre-push 钩子据此拦停。')
        return 1
    print('\n  ✓全测通过%s。' % ('（快测，未含全书检）' if quick else ''))
    return 0


if __name__ == '__main__':
    sys.exit(main())
